WFJ.Data.add("quest", {
  [97243] = { "Il richiamo del fuoco", "Porta la Torch of Dormant Flame a Olariaan Swiftburn allo Shrine of Flames, nei Gustberry Lowlands.", "Anche se siamo nel regno di Skywall, questo resta il piano elementale. Gli spiriti di tutti e quattro gli elementi ci parlano, se ci degniamo di ascoltare. Uno di noi Windshaper è in particolare sintonia con l'elemento del fuoco: uno shen'dorei di nome Olariaan Swiftburn.\n\nPortagli questo allo Shrine of Flames, nei Gustberry Lowlands. Lo troverai nascosto lungo il bordo dell'isola, a ovest di Valanaar.", "Sì, {name}? Che cos'hai lì?", "Dunque hai portato la torcia. Sì, giovane {class}, posso insegnarti a rispondere al richiamo del fuoco. Non sarà facile, ma niente di ciò che facciamo in questo regno è mai facile.", 0x53f3b76b, 0x10e8fa30, 0xb32aea3b, 0xacd1e0ef, 0x89691ed7, "....." },
  [97244] = { "Il richiamo del fuoco", "Uccidi Skypriest Faladiel nei Gustberry Lowlands e raccogli il Faladiel's Heart.", "C'è uno Skypriest degli Al'Aketh di nome Faladiel. Un tempo era un invocatore della fiamma e un fedele Windshaper. Come tanti Al'Aketh, ha barattato la sua lealtà con il potere, e ora le sue mani sono macchiate del sangue dei suoi ex fratelli e sorelle.\n\nTroverai lo Skypriest Faladiel alla fattoria a nord-est, oltre Valanaar, appena a sud dello Shrine of Akir. Uccidi il traditore. Portami il suo cuore. È un compito macabro, ma serve per il rituale che dobbiamo compiere.", "Il cuore di un traditore è un reagente potente. Le fiamme accetteranno avidamente un'offerta simile e arderanno più intense mentre lo consumano.", "I Windshaper non dimenticano, e il sangue si paga sempre con il sangue. Mi compiace che tu sia riuscit<o/a> a consegnare a quel traditore quest'ultimo, doloroso promemoria del nostro credo.\n\nTuttavia, questo cuore non sarà l'unica cosa ad alimentare le fiamme oggi. C'è un altro compito da svolgere.", 0x53f3b76b, 0x7c8f63a5, 0x8ff65707, 0x6c645a00, 0x1c368781, "....." },
  [97245] = { "Il richiamo del fuoco", "Trova la dimora di Kuramaa negli Shen'dar Highlands e sconfiggi lo spirito in combattimento. Quando avrai vinto, porta la Kuramaa's Mask a Olariaan Swiftburn nei Gustberry Lowlands.", "Gli abitanti degli Shen'dar Highlands parlano di un antico spirito della foresta chiamato Kuramaa. Dicono che viva dentro un ceppo contorto in cima a una collina, vicino all'Anchor Pylon degli altipiani.\n\nVa' sugli altipiani e trova quel ceppo. Batti il pugno sulla corteccia e Kuramaa apparirà. Sconfiggi lo spirito in combattimento e portami la sua maschera di legno.\n\nMa sta' attent<o/a>: questa entità sarà straordinariamente resistente a gran parte della tua magia. Solo il tocco della fiamma potrà abbattere lo spirito.", "Lo spirito di Kuramaa è eterno, e si manifesterà di nuovo quando ce ne sarà bisogno. La sua maschera è una fonte di grande potere e si rivelerà preziosissima per il rituale che dobbiamo compiere.", "Ora abbiamo ciò che ci serve. Accenderemo la fiamma eterna e comunicheremo con gli spiriti del fuoco.", 0x53f3b76b, 0xf10b3312, 0x5b054c6d, 0xf9b94402, 0xe1d99925, "....." },
  [97257] = { "Il richiamo del fuoco", "Aspetta che Olariaan inizi il rituale al Brazier of Offering e segui le sue istruzioni.\n\nDevi portare la Fiamma Eterna a Valanaar prima che scada il tempo.", "Ora eseguiremo il rituale.\n\nMetterò i materiali sull'altare e richiamerò gli spiriti della fiamma. Se l'offerta sarà accettata, appariranno e accenderanno la Fiamma Eterna. Allora tu terrai avanti la torcia e catturerai la fiamma.\n\nPorta la torcia accesa a Valanaar e mettila nel Brazier of Eternal Flames. Devi farlo in fretta, perché le fiamme dei Firelands si dissipano rapidamente qui a Skywall.", "Hai fatto bene ad arrivare fin qui. Fai onore ai Windshaper, {name}.", "È fatta. La Fiamma Eterna arde di nuovo.\n\nLa tua prova è completa. Sono lieto di consegnarti il tuo Totem del Fuoco. Usa bene questo simbolo di potere nei tuoi viaggi, {name}.\n\nRicorda solo che il potere del piano elementale serve chi lo rispetta e consuma chi non lo fa. Questa è la nostra via.", 0x53f3b76b, 0x0208cd7e, 0x4a530335, 0x6aa6ef08, 0xaed39338, "....." },
})
